def sumofFactors(n):
    def is_even(x):
        return x % 2 == 0

    even_sum = 0
    for i in range(1, n + 1):
        if n % i == 0 and is_even(i):
            even_sum += i
    return even_sum

# Example usage
assert sumofFactors(18) == 26
