def remove_uppercase(s):
    result = []
    temp = []
    for char in s:
        if char.isupper():
            temp = []  # Clear temp when an uppercase character is encountered
        else:
            temp.append(char)
        if not char.isupper():
            result.extend(temp)  # Append lowercase characters to the result if no uppercase interruption occurs
    return ''.join(result)

