        return sum(int(ch) for ch in sub)

    n = len(s)
    count = 0

    for i in range(n):
        current_sum = 0
        for j in range(i, n):
            current_sum += int(s[j])
            if current_sum == (j - i + 1):  # Check if sum of digits equals substring length
