def merge_dictionaries_three(dict1, dict2, dict3):
    """
    Merges three dictionaries into a single dictionary.

    If there are duplicate keys, the value from the dictionary
    encountered last will overwrite the previous value.
    """
    # Use dictionary unpacking to merge all three dictionaries
    merged_dict = {**dict1, **dict2, **dict3}
    return merged_dict

# Example tests to ensure the function works correctly
